import { createdTrigger } from './created-trigger.now'
import { dailyTrigger } from './daily-trigger.now'
import { inboundEmailTrigger } from './inbound-email-trigger.now'
import { monthlyTrigger } from './monthly-trigger.now'
import { repeatTrigger } from './repeat-trigger.now'
import { runOnceTrigger } from './run-once-trigger.now'
import { serviceCatalogTrigger } from './service-catalog-trigger.now'
import { weeklyTrigger } from './weekly-trigger.now'
import { updatedTrigger } from './updated-trigger.now'
import { createdOrUpdatedTrigger } from './created-or-updated-trigger.now'
import { slaTaskTrigger } from './sla-task-trigger.now'
import { remoteTableQueryTrigger } from './remote-table-query-trigger.now'
import { knowledgeManagementTrigger } from './knowledge-management-trigger.now'

/**
 * Built-in trigger definitions for starting a Flow. Pass a trigger as the first argument to `wfa.trigger()`.
 *
 * ```typescript
 * import { wfa } from '@servicenow/sdk/automation'
 * ```
 * @group Flow
 */
export const trigger = {
    /** Triggers that fire in response to record lifecycle events. */
    record: {
        /** Fires when a record is created on the specified table. */
        created: createdTrigger,
        /** Fires when a record is created or updated on the specified table. */
        createdOrUpdated: createdOrUpdatedTrigger,
        /** Fires when a record is updated on the specified table. */
        updated: updatedTrigger,
    },
    /** Triggers that fire on a time-based schedule. */
    scheduled: {
        /** Fires once per day at the specified time. */
        daily: dailyTrigger,
        /** Fires once per month at the specified day and time. */
        monthly: monthlyTrigger,
        /** Fires repeatedly at a configured interval. */
        repeat: repeatTrigger,
        /** Fires once at a specific date and time. */
        runOnce: runOnceTrigger,
        /** Fires once per week at the specified day and time. */
        weekly: weeklyTrigger,
    },
    /** Application-specific event triggers. */
    application: {
        /** Fires when an inbound email is received. */
        inboundEmail: inboundEmailTrigger,
        /** Fires on a Knowledge Management lifecycle event. */
        knowledgeManagement: knowledgeManagementTrigger,
        /** Fires when a remote table query is executed. */
        remoteTableQuery: remoteTableQueryTrigger,
        /** Fires when a Service Catalog request item is submitted. */
        serviceCatalog: serviceCatalogTrigger,
        /** Fires on an SLA task event. */
        slaTask: slaTaskTrigger,
    },
}
